/// Folder of the model files, from SEMANTIC_MODEL_DIR.
fn model_dir() -> PathBuf {
    let dir = PathBuf::from(std::env::var("SEMANTIC_MODEL_DIR").expect("set SEMANTIC_MODEL_DIR to a folder with vision.onnx, text.onnx, tokenizer.json"));
    assert!(dir.join("tokenizer.json").is_file(), "{} has no tokenizer.json", dir.display());
    dir
}

/// ONNX Runtime library: ORT_DYLIB_PATH, otherwise the `models/` folder of an installed application (release, then development build).
fn runtime_library() -> PathBuf {
    if let Ok(path) = std::env::var("ORT_DYLIB_PATH") { return PathBuf::from(path); }
    let name = if cfg!(windows) { "onnxruntime.dll" } else { "libonnxruntime.so" };
    let data_root = if cfg!(windows) {
        std::env::var("LOCALAPPDATA").map(PathBuf::from)
    } else {
        std::env::var("HOME").map(|home| PathBuf::from(home).join(".local").join("share"))
    }
    .expect("no data folder");
    ["com.alexh3o.photoboggan", "com.alexh3o.photoboggan.dev"]
        .iter()
        .map(|identifier| data_root.join(identifier).join("data").join("models").join(name))
        .find(|path| path.is_file())
        .expect("ONNX Runtime library not found: set ORT_DYLIB_PATH")
}

#[test]
#[ignore = "needs the SigLIP 2 model"]
fn token_ids_match_the_reference() {
    let model = active_model();
    let tokenizer = TextTokenizer::load(&model_dir().join("tokenizer.json"), model).expect("tokenizer");
    for text in reference()["texts"].as_array().unwrap() {
        let fed = normalise_query(text["raw"].as_str().unwrap(), model);
        let expected: Vec<i64> = text["input_ids"].as_array().unwrap().iter().map(|id| id.as_i64().unwrap()).collect();
        assert_eq!(tokenizer.ids(&fed).unwrap(), expected, "{fed:?}");
    }
}

#[test]
#[ignore = "needs the SigLIP 2 model"]
fn image_embeddings_match_the_reference() {
    let model = active_model();
    let environment = crate::onnx_runtime::environment(&runtime_library()).expect("ONNX Runtime");
    let mut encoder = VisionEncoder::load(&environment, &model_dir().join("vision.onnx"), model, 2).expect("vision model");
    let images = reference()["images"].as_array().unwrap().clone();
    let mut pixels = Vec::new();
    for image in &images {
        let (rgb, width, height) = crate::integrity::decode_png(&fixtures_dir().join(image["file"].as_str().unwrap()), true).unwrap();
        pixels.extend(image_tensor(&rgb, width, height, model));
    }
    let embeddings = encoder.embed(pixels, images.len()).expect("inference");
    for (image, embedding) in images.iter().zip(&embeddings) {
        let similarity = cosine(embedding, &floats(&image["embedding"]));
        println!("{}: cos = {similarity:.6}", image["file"]);
        assert!(similarity >= 0.999, "{}: cos = {similarity}", image["file"]);
        // Stored in fp16, the vector stays as close.
        let stored = blob_to_vector(&vector_to_blob(embedding), model.embed_dim).unwrap();
        assert!(cosine(&stored, &floats(&image["embedding"])) >= 0.999);
    }
}

#[test]
#[ignore = "needs the SigLIP 2 model"]
fn text_embeddings_match_the_reference() {
    let model = active_model();
    let dir = model_dir();
    let environment = crate::onnx_runtime::environment(&runtime_library()).expect("ONNX Runtime");
    let mut encoder = TextEncoder::load(&environment, &dir.join("text.onnx"), &dir.join("tokenizer.json"), model, 2).expect("text model");
    let texts = reference()["texts"].as_array().unwrap().clone();
    let fed: Vec<String> = texts.iter().map(|text| normalise_query(text["raw"].as_str().unwrap(), model)).collect();
    let embeddings = encoder.embed(&fed).expect("inference");
    for (text, embedding) in texts.iter().zip(&embeddings) {
        let similarity = cosine(embedding, &floats(&text["embedding"]));
        println!("{:?}: cos = {similarity:.6}", text["fed"]);
        assert!(similarity >= 0.999, "{:?}: cos = {similarity}", text["fed"]);
    }
}

/// Paths of the model files of SEMANTIC_MODEL_DIR and of the ONNX Runtime library.
fn model_paths() -> crate::semantic_models::ModelPaths {
    let dir = model_dir();
    crate::semantic_models::ModelPaths {
        runtime: runtime_library(),
        vision: dir.join("vision.onnx"),
        text: dir.join("text.onnx"),
        tokenizer: dir.join("tokenizer.json"),
    }
}

#[test]
#[ignore = "needs the SigLIP 2 model"]
fn a_scan_stores_what_the_encoder_computes_and_stops_when_asked() {
    let model = active_model();
    let (_catalog, pool) = temp_catalog();
    let photos = tempfile::tempdir().unwrap();
    let thumbnails = tempfile::tempdir().unwrap();
    let conn = pool.get().unwrap();
    // 20 synthetic photos (two batches), one unreadable, one video without thumbnail.
    let mut ids = Vec::new();
    for seed in 0..20u64 {
        let path = photos.path().join(format!("p{seed}.jpg"));
        std::fs::write(&path, crate::test_support::jpeg_from_rgb(&crate::test_support::blobs_rgb(320, 240, seed), 320, 240, 90)).unwrap();
        ids.push(add_photo(&conn, &path.to_string_lossy(), 1, seed as i64));
    }
    let broken = photos.path().join("broken.jpg");
    std::fs::write(&broken, b"not a jpeg").unwrap();
    add_photo(&conn, &broken.to_string_lossy(), 1, 1);
    let video = photos.path().join("clip.mp4");
    std::fs::write(&video, b"not a video").unwrap();
    add_photo(&conn, &video.to_string_lossy(), 1, 1);

    let job = |cancel: Arc<AtomicBool>| ScanJob {
        pool: pool.clone(),
        models_dir: PathBuf::new(),
        thumbnails_dir: thumbnails.path().to_path_buf(),
        photo_ids: None,
        folder: None,
        recursive: true,
        threads: 2,
        cancel,
    };
    let scan = |cancel: Arc<AtomicBool>, emit: &dyn Fn(ScanProgress)| {
        let targets = select_targets(&conn, MODEL, None, None, true).unwrap();
        let total = targets.len();
        let pending: Vec<Target> = targets.into_iter().filter(|target| target.standing == Standing::Pending).collect();
        let report = ScanReport { total, up_to_date: total - pending.len(), ..ScanReport::default() };
        scan_pending(job(cancel), &model_paths(), &conn, pending, report, emit).expect("scan")
    };

    // Stop requested after the first batch: 16 photos stored, the rest left for the next run.
    let cancel = Arc::new(AtomicBool::new(false));
    let events = Mutex::new(Vec::new());
    let report = scan(cancel.clone(), &|progress| {
        cancel.store(true, Ordering::SeqCst);
        events.lock().unwrap().push(progress);
    });
    assert!(report.cancelled);
    assert_eq!(report.analysed + report.skipped + report.failed.len(), 16);
    {
        let events = events.lock().unwrap();
        assert_eq!((events[0].done, events[0].total, events[0].paused), (16, 22, false));
        assert!(events[0].remaining_seconds.is_some());
    }

    // Second run: the rest only.
    let report = scan(Arc::new(AtomicBool::new(false)), &|_| {});
    assert!(!report.cancelled);
    assert_eq!(report.up_to_date, 16);
    assert_eq!(report.analysed + report.skipped + report.failed.len(), 6);
    assert_eq!(stats(&conn, None, None, false).unwrap(), Stats { total: 22, analysed: 20, failed: 1, pending: 1, bytes: 20 * (768 * 2 + ROW_OVERHEAD) });

    // Stored vectors are those of the encoder on the same pixels.
    let environment = crate::onnx_runtime::environment(&runtime_library()).unwrap();
    let mut encoder = VisionEncoder::load(&environment, &model_dir().join("vision.onnx"), model, 2).unwrap();
    let path: String = conn.query_row("SELECT path FROM photos WHERE id = ?1", [ids[7]], |row| row.get(0)).unwrap();
    let direct = encoder.embed(prepare(&path, thumbnails.path(), model).ok().unwrap(), 1).unwrap().remove(0);
    let blob: Vec<u8> = conn.query_row("SELECT vec FROM photo_embeddings WHERE photo_id = ?1", [ids[7]], |row| row.get(0)).unwrap();
    assert!(cosine(&direct, &blob_to_vector(&blob, model.embed_dim).unwrap()) > 0.9999);
}
